import{_ as e,o as r,c as d,ah as a}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Présentation","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/overview.md","filePath":"src/guide/overview.md"}'),s={name:"guide/overview.md"};function n(i,t,o,l,c,u){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="presentation" tabindex="-1">Présentation <a class="header-anchor" href="#presentation" aria-label="Permalink to &quot;Présentation&quot;">​</a></h1><p><strong>Kura</strong> est la plateforme administrative et financière de <strong>NextBoxx</strong>, l&#39;organisme de formation d&#39;edPage group. Elle centralise le catalogue, les cohortes, les candidatures, les inscriptions, la facturation, la certification et les rémunérations. C&#39;est le système de vérité unique pour tout ce qui n&#39;est pas pédagogique.</p><h2 id="l-ecosysteme-nextboxx" tabindex="-1">L&#39;écosystème NextBoxx <a class="header-anchor" href="#l-ecosysteme-nextboxx" aria-label="Permalink to &quot;L&#39;écosystème NextBoxx&quot;">​</a></h2><p>L&#39;activité repose sur quatre briques distinctes :</p><table tabindex="0"><thead><tr><th>Brique</th><th>Rôle</th></tr></thead><tbody><tr><td><strong>Site NextBoxx</strong></td><td>Vitrine publique : catalogue, dépôt de candidature, inscription aux événements. Sans état, il transmet à Kura par API.</td></tr><tr><td><strong>Kura</strong></td><td>Socle administratif et financier : identité, admission, cohortes, inscriptions, facturation, certification, rémunérations, documents. Ce guide.</td></tr><tr><td><strong>Sève</strong></td><td>LMS Moodle rebrandé : contenus, classes virtuelles, évaluations, présence, accompagnement.</td></tr><tr><td><strong>Parcours Canopé</strong></td><td>Statut et communauté des anciens apprenants certifiés.</td></tr></tbody></table><p>Kura est le <strong>fournisseur d&#39;identité</strong> OAuth2/OpenID Connect de Sève : un compte NextBoxx donne accès à Sève par SSO, sans mot de passe Moodle. Sève ne stocke aucune donnée financière ou contractuelle et ne remonte à Kura que des données agrégées (présence, complétion, notes).</p><h2 id="principes-directeurs" tabindex="-1">Principes directeurs <a class="header-anchor" href="#principes-directeurs" aria-label="Permalink to &quot;Principes directeurs&quot;">​</a></h2><ul><li><strong>Un seul compte par personne</strong>, dédoublonné par email ; les rôles se cumulent, on ne recrée jamais de compte.</li><li><strong>Kura décide, Sève exécute.</strong> Aucune décision administrative ou financière (ouverture de cohorte, validation d&#39;inscription, facturation, certificat) n&#39;a lieu dans Sève.</li><li><strong>Le site public est sans état.</strong> Une candidature ou une inscription acceptée est renvoyée au CMS du site, jamais l&#39;inverse.</li><li><strong>Les notifications n&#39;exécutent rien.</strong> Elles rappellent et alertent ; les décisions restent humaines, sauf les passages automatiques prévus par les règles métier.</li><li><strong>Montants en FCFA</strong>, stockés en <code>DECIMAL(12,2)</code>, exprimés hors taxe.</li><li><strong>Traçabilité</strong> : les actions des comptes à privilèges sur les comptes et les rôles sont journalisées.</li></ul><h2 id="perimetre" tabindex="-1">Périmètre <a class="header-anchor" href="#perimetre" aria-label="Permalink to &quot;Périmètre&quot;">​</a></h2><p>Le <strong>socle</strong> couvre les modules 1 à 18, le module 29 (Compte NextBoxx), transversal, et le module 32 (Documents générés), nécessaire aux livrets, conventions, factures et certificats.</p><p>Les <strong>activités élargies</strong> (modules 19 à 28, 30, 31 et 33) prolongent le socle : formation B2B sur devis, événements, demandes entreprises et recrutement, financement d&#39;événements, incubation L&#39;Éclosion et partenariats technologiques.</p><table tabindex="0"><thead><tr><th>#</th><th>Module</th><th>Bloc</th></tr></thead><tbody><tr><td>1</td><td>Catalogue de formations</td><td>Socle</td></tr><tr><td>2</td><td>Gestion des cohortes</td><td>Socle</td></tr><tr><td>3</td><td>Inscriptions et dossier apprenant</td><td>Socle</td></tr><tr><td>4</td><td>Suivi de présence (vue Kura)</td><td>Socle</td></tr><tr><td>5</td><td>Évaluations et résultats (vue Kura)</td><td>Socle</td></tr><tr><td>6</td><td>Certification (certificat, attestation partielle)</td><td>Socle</td></tr><tr><td>7</td><td>Facturation NextBoxx (30/40/30, paiement en ligne)</td><td>Socle</td></tr><tr><td>8</td><td>Communication (annonces, rappels)</td><td>Socle</td></tr><tr><td>9</td><td>Reporting</td><td>Socle</td></tr><tr><td>10</td><td>Rémunération des formateurs et coachs</td><td>Socle</td></tr><tr><td>11</td><td>Commissions apporteurs d&#39;affaires</td><td>Socle</td></tr><tr><td>12</td><td>Partenaires marketing</td><td>Socle</td></tr><tr><td>13</td><td>Tableau de bord — décision de report de session</td><td>Socle</td></tr><tr><td>14</td><td>Intégration avec Sève</td><td>Socle</td></tr><tr><td>15</td><td>Tableau de bord Direction</td><td>Socle</td></tr><tr><td>16</td><td>Espace financeur (entreprise)</td><td>Socle</td></tr><tr><td>17</td><td>Signature électronique</td><td>Socle</td></tr><tr><td>18</td><td>Gestion des candidatures et admission (dont test QCM)</td><td>Socle</td></tr><tr><td>19</td><td>Formation B2B sur devis</td><td>Élargi</td></tr><tr><td>20–22</td><td>Événements (création, inscriptions, financement)</td><td>Élargi</td></tr><tr><td>23–26</td><td>Demandes entreprises, mise en relation et recrutement</td><td>Élargi</td></tr><tr><td>27–28</td><td>Financement d&#39;événements et espace financeur d&#39;événement</td><td>Élargi</td></tr><tr><td>29</td><td>Compte NextBoxx (un compte, plusieurs rôles)</td><td>Transversal</td></tr><tr><td>30–31</td><td>Incubation L&#39;Éclosion et participations</td><td>Élargi</td></tr><tr><td>32</td><td>Documents générés</td><td>Socle</td></tr><tr><td>33</td><td>Partenariats technologiques</td><td>Élargi</td></tr></tbody></table><h2 id="reperes-chiffres" tabindex="-1">Repères chiffrés <a class="header-anchor" href="#reperes-chiffres" aria-label="Permalink to &quot;Repères chiffrés&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repère</th><th>Valeur</th></tr></thead><tbody><tr><td>Référentiels au lancement</td><td>40, en 3 catégories</td></tr><tr><td>Rentrées annuelles</td><td>4 promotions : Baobab (septembre), Iroko (décembre), Acacia (mars), Karité (juin)</td></tr><tr><td>Capacité d&#39;une cohorte</td><td>15 apprenants</td></tr><tr><td>Classes virtuelles simultanées</td><td>10 au maximum, 15 participants par classe</td></tr><tr><td>Échéancier</td><td>3 tranches : 30 % à la signature, 40 % à mi-parcours, 30 % à la fin</td></tr><tr><td>Seuil de réussite du test d&#39;admission</td><td>60 %, soit 6 bonnes réponses sur 10</td></tr><tr><td>Seuil d&#39;alerte d&#39;absence</td><td>30 % du volume horaire</td></tr><tr><td>Commission apporteur d&#39;affaires</td><td>5 % des sommes encaissées</td></tr><tr><td>Conservation des factures et conventions</td><td>10 ans (OHADA)</td></tr></tbody></table><h2 id="par-ou-continuer" tabindex="-1">Par où continuer <a class="header-anchor" href="#par-ou-continuer" aria-label="Permalink to &quot;Par où continuer&quot;">​</a></h2><ul><li><a href="/kura-guide/guide/getting-started.html">Démarrage</a> — installer et lancer Kura en local.</li><li><a href="/kura-guide/guide/architecture.html">Architecture</a> — stack, structure du code et modèle de données.</li><li><a href="/kura-guide/guide/roles.html">Comptes et rôles</a> — qui peut faire quoi.</li><li><a href="/kura-guide/guide/learner-journey.html">Parcours apprenant</a> — de la candidature au Parcours Canopé.</li><li><a href="/kura-guide/guide/core-modules.html">Modules du socle</a> — les règles métier du quotidien.</li></ul>',16)])])}const h=e(s,[["render",n]]);export{m as __pageData,h as default};
